using BotZone.Contracts;
using System.Text.Json;
namespace BotZone.Infrastructure.Services;
public sealed class ReadService(SqlStore sql, ProductPhotoCatalog? photos = null)
{
 public async Task<object> Catalogue(string locale,string q="",string category="",string? slug=null){locale=locale=="en"?"en":"vi";var products=await sql.Rows("""
 SELECT p.id,p.slug,p.model_code AS "modelCode",c.code AS category,t.name,t.description,p.source_url AS "sourceUrl",p.specs,p.poster,
 COALESCE((SELECT jsonb_agg(jsonb_build_object('id',v.id,'sku',v.sku,'options',v.options,'priceVnd',v.price_vnd::text,'available',s.available,'trackingMode',v.tracking_mode,'careFeeVnd',v.care_fee_vnd::text,'standardWarrantyMonths',v.standard_warranty_months,'active',v.active) ORDER BY v.sku) FROM product_variants v JOIN variant_stock s ON s.variant_id=v.id WHERE v.product_id=p.id AND v.active),'[]') variants,
 COALESCE((SELECT jsonb_agg(cp.slug) FROM product_compatibilities pc JOIN products cp ON cp.id=pc.target_product_id WHERE pc.accessory_product_id=p.id),'[]') AS "compatibleProducts"
 FROM products p JOIN categories c ON c.id=p.category_id JOIN product_translations t ON t.product_id=p.id AND t.locale=$1
 WHERE p.business_status='active' AND t.content_status='published' AND c.active AND ($2='' OR t.name ILIKE '%'||$2||'%' OR p.model_code ILIKE '%'||$2||'%') AND ($3='' OR lower(c.code)=lower($3)) AND ($4::text IS NULL OR p.slug=$4) ORDER BY p.model_code
 """,locale,q.Length>200?q[..200]:q,category,slug);photos?.Attach(products,locale);CataloguePresentation.Attach(products,locale);if(slug is not null)return new{product=products.FirstOrDefault()??throw new BusinessException("NOT_FOUND","Không tìm thấy sản phẩm.",404)};var rate=await sql.Optional("SELECT value FROM app_settings WHERE key='exchangeRateVnd'");return new{products,categories=await sql.Rows("SELECT code,name_vi AS \"nameVi\",name_en AS \"nameEn\" FROM categories WHERE active ORDER BY code"),exchangeRateVnd=rate?.J("value").ToString()??"25000"};}
 public async Task<object> Landing(){var row=await sql.Optional("SELECT v.version_no AS revision,v.sections FROM landing_publications p JOIN landing_versions v ON v.id=p.version_id JOIN landing_pages lp ON lp.id=p.page_id WHERE lp.slug='home' ORDER BY p.published_at DESC LIMIT 1");return row??new Dictionary<string,object?>{{"revision",0},{"sections",Array.Empty<object>()}};}
 public async Task<object> Cart(Actor a){Access.Require(a,"customer");return new{items=await sql.Rows("SELECT ci.variant_id AS \"variantId\",ci.quantity,ci.care FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.customer_id=$1 ORDER BY ci.id",a.Id),promotionCode=(await sql.Optional("SELECT p.code_normalized AS code FROM carts c JOIN promotion_versions v ON v.id=c.applied_promotion_version_id JOIN promotions p ON p.id=v.promotion_id WHERE c.customer_id=$1",a.Id))?.S("code")??""};}
 public async Task<object> Orders(Actor a){Access.Require(a,"customer","owner","order_staff","warehouse_staff");return new{orders=await sql.Rows("SELECT id,order_no,order_status,"+(a.Role=="warehouse_staff"?"":"payment_method,total_vnd,")+"created_at,expires_at,delivered_at,responsible_staff_id FROM orders WHERE ($1<>'customer' OR customer_id=$2) AND order_status<>'building' ORDER BY created_at DESC,id LIMIT 200",a.Role,a.Id)};}
 public async Task<Dictionary<string,object?>> Order(Actor a,Guid id){Access.Require(a,"customer","owner","order_staff","warehouse_staff");return await sql.One("SELECT * FROM orders WHERE id=$1 AND ($2<>'customer' OR customer_id=$3)",id,a.Role,a.Id);}
 public async Task<object> OrderDetail(Actor a,Guid id){var order=await Order(a,id);if(a.Role=="warehouse_staff"){var packingOrder=order.Where(x=>new[]{"id","order_no","order_status","created_at","delivered_at","address_snapshot","responsible_staff_id"}.Contains(x.Key)).ToDictionary(x=>x.Key,x=>x.Value);return new{order=packingOrder,items=await sql.Rows("SELECT id,line_no,variant_id,quantity,snapshot->'name' AS product_name,snapshot->'sku' AS sku,snapshot->'options' AS options FROM order_items WHERE order_id=$1 ORDER BY line_no",id),units=await sql.Rows("SELECT u.id,u.order_item_id,u.unit_ordinal,ia.inventory_unit_id,COALESCE((SELECT jsonb_agg(jsonb_build_object('kind',ii.kind,'value',ii.normalized_value)) FROM inventory_identifiers ii WHERE ii.inventory_unit_id=ia.inventory_unit_id),'[]') identifiers FROM order_item_unit_amounts u JOIN order_items oi ON oi.id=u.order_item_id LEFT JOIN inventory_allocations ia ON ia.order_item_unit_amount_id=u.id AND ia.state<>'released' WHERE oi.order_id=$1 ORDER BY oi.line_no,u.unit_ordinal",id),shipments=await sql.Rows("SELECT * FROM shipments WHERE order_id=$1 ORDER BY created_at",id)};}return new{order,items=await sql.Rows("SELECT * FROM order_items WHERE order_id=$1 ORDER BY line_no",id),units=await sql.Rows("SELECT u.*,ia.inventory_unit_id,COALESCE((SELECT jsonb_agg(jsonb_build_object('kind',ii.kind,'value',ii.normalized_value)) FROM inventory_identifiers ii WHERE ii.inventory_unit_id=ia.inventory_unit_id),'[]') identifiers FROM order_item_unit_amounts u JOIN order_items oi ON oi.id=u.order_item_id LEFT JOIN inventory_allocations ia ON ia.order_item_unit_amount_id=u.id AND ia.state<>'released' WHERE oi.order_id=$1 ORDER BY oi.line_no,u.unit_ordinal",id),attempts=await sql.Rows("SELECT * FROM payment_attempts WHERE order_id=$1 ORDER BY created_at",id),receipts=await sql.Rows("SELECT * FROM payment_receipts WHERE order_id=$1 ORDER BY received_at",id),shipments=await sql.Rows("SELECT s.*,COALESCE((SELECT jsonb_agg(e ORDER BY occurred_at) FROM shipment_events e WHERE e.shipment_id=s.id),'[]') events FROM shipments s WHERE order_id=$1 ORDER BY created_at",id),invoice=await sql.Optional("SELECT id,invoice_no,lifecycle,issued_at,grand_total_vnd FROM invoices WHERE order_id=$1 AND ($2<>'customer' OR lifecycle='issued')",id,a.Role)};}
 public async Task<object> Account(Actor a,string locale="vi"){Access.Require(a,"customer");var balance=await sql.One("SELECT COALESCE(sc.balance_vnd,0) credit,COALESCE(la.balance_points,0) points,COALESCE(la.net_spend_vnd,0) spend FROM \"user\" u LEFT JOIN store_credit_accounts sc ON sc.user_id=u.id LEFT JOIN loyalty_accounts la ON la.user_id=u.id WHERE u.id=$1",a.Id);return new{creditVnd=balance.S("credit"),points=balance.I("points"),tier=balance.L("spend")>=100000000?"Platinum":balance.L("spend")>=50000000?"Gold":balance.L("spend")>=20000000?"Silver":"Member",profile=await sql.Optional("SELECT display_name,phone FROM customer_profiles WHERE user_id=$1",a.Id),creditEntries=await sql.Rows("SELECT * FROM store_credit_entries WHERE user_id=$1 ORDER BY created_at DESC LIMIT 200",a.Id),loyaltyEntries=await sql.Rows("SELECT * FROM loyalty_entries WHERE user_id=$1 ORDER BY created_at DESC LIMIT 200",a.Id),addresses=await sql.Rows("SELECT * FROM addresses WHERE user_id=$1 ORDER BY is_default DESC,id",a.Id),notifications=CustomerNotificationPresentation.Localize(await sql.Rows("SELECT * FROM notifications WHERE recipient_user_id=$1 ORDER BY created_at DESC LIMIT 200",a.Id),locale),wishlist=(await sql.Rows("SELECT product_id FROM wishlists WHERE user_id=$1",a.Id)).Select(r=>r.S("product_id")),tradeIns=await sql.Rows("SELECT r.*,COALESCE((SELECT jsonb_agg(i) FROM trade_in_items i WHERE i.request_id=r.id),'[]') items,COALESCE((SELECT jsonb_agg(to_jsonb(q)||jsonb_build_object('items',COALESCE((SELECT jsonb_agg(qi) FROM trade_in_quote_items qi WHERE qi.quote_id=q.id),'[]')) ORDER BY version_no DESC) FROM trade_in_quotes q WHERE q.request_id=r.id),'[]') quotes FROM trade_in_requests r WHERE customer_id=$1 ORDER BY created_at DESC",a.Id),returns=await sql.Rows("SELECT * FROM return_requests WHERE customer_id=$1 ORDER BY created_at DESC",a.Id),entitlements=await sql.Rows("SELECT e.*,oi.snapshot,oi.order_id FROM warranty_entitlements e JOIN order_item_unit_amounts u ON u.id=e.order_item_unit_amount_id JOIN order_items oi ON oi.id=u.order_item_id JOIN orders o ON o.id=oi.order_id WHERE o.customer_id=$1",a.Id),claims=await sql.Rows("SELECT c.* FROM warranty_claims c JOIN warranty_entitlements e ON e.id=c.entitlement_id JOIN order_item_unit_amounts u ON u.id=e.order_item_unit_amount_id JOIN order_items i ON i.id=u.order_item_id JOIN orders o ON o.id=i.order_id WHERE o.customer_id=$1 ORDER BY c.created_at DESC",a.Id)};}
 public async Task<object> Overview(Actor a){Access.Require(a,"owner","order_staff","warehouse_staff","content_staff");var result=new Dictionary<string,object?>{{"demoMode",true},{"role",a.Role}};if(a.Role is "owner" or "order_staff")result["orders"]=await sql.Rows("SELECT order_status,count(*)::int count FROM orders GROUP BY order_status ORDER BY order_status");if(a.Role is "owner" or "warehouse_staff")result["lowStock"]=await sql.Rows("SELECT v.id,v.sku,s.available FROM variant_stock s JOIN product_variants v ON v.id=s.variant_id WHERE s.available<5 ORDER BY s.available,v.sku");if(a.Role is "owner" or "content_staff")result["drafts"]=await sql.Rows("SELECT p.slug,d.revision,d.updated_at FROM landing_drafts d JOIN landing_pages p ON p.id=d.page_id");return result;}
 public async Task<object> AdminData(Actor a,string module,string q,int page,int pageSize){var spec=module switch{
  "categories"=>("SELECT id,code,slug,name_vi,name_en,active FROM categories",new[]{"owner"}),
  "catalogue"=>("SELECT p.id,p.slug,p.model_code,p.business_status,t.name,v.id variant_id,v.sku,v.price_vnd,v.care_fee_vnd,v.standard_warranty_months,v.active,s.available FROM products p JOIN product_translations t ON t.product_id=p.id AND t.locale='vi' JOIN product_variants v ON v.product_id=p.id JOIN variant_stock s ON s.variant_id=v.id",new[]{"owner","order_staff","warehouse_staff","content_staff"}),
  "inventory"=>("SELECT l.id,l.variant_id,v.sku,l.qty_on_hand,l.qty_reserved,l.received_at,l.unit_cost_vnd FROM inventory_lots l JOIN product_variants v ON v.id=l.variant_id",new[]{"owner","warehouse_staff"}),
  "purchases"=>("SELECT p.id,p.code,p.status,s.name supplier,p.created_at FROM purchase_orders p JOIN suppliers s ON s.id=p.supplier_id",new[]{"owner","warehouse_staff"}),
  "suppliers"=>("SELECT id,code,name,contact,active FROM suppliers",new[]{"owner","warehouse_staff"}),
  "orders"=>("SELECT id,order_no,order_status,payment_method,total_vnd,created_at,customer_id,responsible_staff_id FROM orders",new[]{"owner","order_staff","warehouse_staff"}),
  "payments"=>("SELECT a.id,o.order_no,a.method,a.status,a.requested_amount_vnd,a.created_at FROM payment_attempts a JOIN orders o ON o.id=a.order_id",new[]{"owner","order_staff"}),
  "returns"=>("SELECT * FROM return_requests",new[]{"owner","order_staff","warehouse_staff"}),
  "trade-in" or "tradeins" or "trade_ins"=>("SELECT * FROM trade_in_requests",new[]{"owner","order_staff","warehouse_staff"}),
  "warranty"=>("SELECT c.*,i.variant_id FROM warranty_claims c JOIN warranty_entitlements e ON e.id=c.entitlement_id JOIN order_item_unit_amounts u ON u.id=e.order_item_unit_amount_id JOIN order_items i ON i.id=u.order_item_id",new[]{"owner","order_staff","warehouse_staff"}),
  "customers"=>("SELECT c.user_id id,c.display_name,c.phone,u.email,u.email_verified,COALESCE(sc.balance_vnd,0)::text credit_vnd,COALESCE(la.balance_points,0) balance_points,COALESCE(la.net_spend_vnd,0)::text net_spend_vnd,CASE WHEN COALESCE(la.net_spend_vnd,0)>=100000000 THEN 'Platinum' WHEN COALESCE(la.net_spend_vnd,0)>=50000000 THEN 'Gold' WHEN COALESCE(la.net_spend_vnd,0)>=20000000 THEN 'Silver' ELSE 'Member' END tier,(SELECT count(*)::int FROM orders o WHERE o.customer_id=c.user_id AND o.order_status<>'building') order_count FROM customer_profiles c JOIN \"user\" u ON u.id=c.user_id LEFT JOIN store_credit_accounts sc ON sc.user_id=c.user_id LEFT JOIN loyalty_accounts la ON la.user_id=c.user_id",new[]{"owner","order_staff"}),
  "promotions"=>("SELECT p.id,p.code_normalized,p.active,p.max_uses,p.max_uses_per_customer FROM promotions p",new[]{"owner","order_staff","content_staff"}),
  "staff"=>("SELECT s.user_id id,s.staff_code,s.role,s.active,u.name,u.email FROM staff_profiles s JOIN \"user\" u ON u.id=s.user_id",new[]{"owner"}),
  "settings"=>("SELECT key id,value,version FROM app_settings WHERE key IN ('commerce','exchangeRateVnd','store','tradeIn')",new[]{"owner"}),
  "audit"=>("SELECT id,actor_user_id,action,entity_type,entity_id,reason,occurred_at FROM audit_events",new[]{"owner","order_staff","warehouse_staff","content_staff"}),
  "stock_adjustments"=>("SELECT a.*,v.sku FROM stock_adjustments a JOIN inventory_lots l ON l.id=a.lot_id JOIN product_variants v ON v.id=l.variant_id",new[]{"owner","warehouse_staff"}),
  "refunds"=>("SELECT r.*,o.order_no FROM refunds r JOIN orders o ON o.id=r.order_id",new[]{"owner","order_staff"}),
  "media"=>("SELECT id,visibility,mime,size_bytes,validation_status,source_url,license_note,created_at FROM media_assets WHERE visibility='public'",new[]{"owner","content_staff"}),
  _=>throw new BusinessException("NOT_FOUND","Module không tồn tại.",404)};Access.Require(a,spec.Item2);if(a.Role=="warehouse_staff"&&module=="orders")spec=("SELECT id,order_no,order_status,created_at,responsible_staff_id FROM orders WHERE order_status<>'building'",spec.Item2);if(module=="inventory")spec=("SELECT l.id,l.variant_id,v.sku,l.received_at,CASE WHEN v.tracking_mode='serialized' THEN (SELECT count(*) FROM inventory_units u WHERE u.lot_id=l.id AND u.custody_status IN('available','reserved') AND u.condition_status='new') ELSE l.qty_on_hand END::int qty_on_hand,CASE WHEN v.tracking_mode='serialized' THEN (SELECT count(*) FROM inventory_units u WHERE u.lot_id=l.id AND u.custody_status='reserved') ELSE l.qty_reserved END::int qty_reserved,CASE WHEN v.tracking_mode='serialized' THEN (SELECT count(*) FROM inventory_units u WHERE u.lot_id=l.id AND u.custody_status IN('quarantine','service')) ELSE (SELECT COALESCE(sum(quantity),0) FROM inventory_quarantine iq WHERE iq.lot_id=l.id AND iq.state IN('quarantine','service')) END::int quarantine"+(a.Role=="owner"?",l.unit_cost_vnd":"")+" FROM inventory_lots l JOIN product_variants v ON v.id=l.variant_id",spec.Item2);q=q.Length>200?q[..200]:q;page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,1,100);var query=spec.Item1;if(module=="audit"&&a.Role!="owner"){var actions=a.Role switch{"content_staff"=>"'save_landing','publish_landing','restore_landing','preview_landing','revoke_landing_preview','upload_media','update_translation'","warehouse_staff"=>"'receive_goods','request_stock_adjustment','handoff','inspect_return','receive_return','receive_trade_in','inspect_trade_in','process_warranty'",_=>"'confirm_order','record_payment','shipment_event','cancel_order','create_invoice_draft','approve_return_intake','quote_trade_in'"};query+=$" WHERE action IN ({actions})";}var rows=await sql.Rows($"SELECT * FROM ({query}) d WHERE ($1='' OR to_jsonb(d)::text ILIKE '%'||$1||'%') ORDER BY id LIMIT $2 OFFSET $3",q.Length>200?q[..200]:q,pageSize,(page-1)*pageSize);var count=await sql.One($"SELECT count(*)::int n FROM ({query}) d WHERE ($1='' OR to_jsonb(d)::text ILIKE '%'||$1||'%')",q);return new{rows,columns=rows.FirstOrDefault()?.Keys.ToArray()??[],totalCount=count.I("n"),page,pageSize};}
 public async Task<object> Lookups(Actor a){Access.Require(a,"owner","order_staff","warehouse_staff","content_staff");return new{categories=await sql.Rows("SELECT id,name_vi name FROM categories WHERE active ORDER BY code"),tradeInQuotes=a.Role is "owner" or "order_staff" or "warehouse_staff"?await sql.Rows("SELECT q.id,'Báo giá v'||q.version_no::text name,q.request_id AS \"requestId\",CASE WHEN approved_by IS NULL THEN 'awaiting_approval' ELSE 'approved' END status FROM trade_in_quotes q ORDER BY q.request_id,q.version_no DESC"):[],customers=a.Role is "owner" or "order_staff"?await sql.Rows("SELECT user_id id,display_name name FROM customer_profiles ORDER BY display_name LIMIT 1000"):[],tradeInItems=a.Role is "owner" or "order_staff" or "warehouse_staff"?await sql.Rows("SELECT id,internal_code name,request_id AS \"requestId\",state FROM trade_in_items ORDER BY internal_code"):[],quoteItems=a.Role is "owner" or "order_staff" or "warehouse_staff"?await sql.Rows("SELECT qi.id,ti.internal_code name,qi.item_id AS \"itemId\",qi.quote_id AS \"quoteId\",qi.request_id AS \"requestId\",qi.decision FROM trade_in_quote_items qi JOIN trade_in_items ti ON ti.id=qi.item_id"):[],staff=a.Role is "owner" or "order_staff"?await sql.Rows("SELECT s.user_id id,u.name,s.staff_code FROM staff_profiles s JOIN \"user\" u ON u.id=s.user_id WHERE s.active ORDER BY s.staff_code"):[],products=await sql.Rows("SELECT p.id,p.slug,t.name FROM products p JOIN product_translations t ON t.product_id=p.id AND t.locale='vi' ORDER BY p.slug"),variants=await sql.Rows("SELECT id,sku name,product_id FROM product_variants ORDER BY sku"),suppliers=a.Role is "owner" or "warehouse_staff"?await sql.Rows("SELECT id,name FROM suppliers WHERE active ORDER BY name"):[],lots=a.Role is "owner" or "warehouse_staff"?await sql.Rows("SELECT l.id,v.sku||' · '||l.id::text name,l.variant_id,l.qty_on_hand,l.qty_reserved FROM inventory_lots l JOIN product_variants v ON v.id=l.variant_id ORDER BY l.received_at"):[],purchaseItems=a.Role is "owner" or "warehouse_staff"?await sql.Rows("SELECT i.id,v.sku name,i.purchase_order_id AS \"purchaseOrderId\",i.quantity FROM purchase_order_items i JOIN product_variants v ON v.id=i.variant_id"):[],inventoryUnits=a.Role is "owner" or "warehouse_staff"?await sql.Rows("SELECT u.id,COALESCE((SELECT string_agg(normalized_value,', ') FROM inventory_identifiers WHERE inventory_unit_id=u.id),u.id::text) name,u.custody_status,u.condition_status,u.lot_id AS \"lotId\",l.variant_id AS \"variantId\" FROM inventory_units u JOIN inventory_lots l ON l.id=u.lot_id LIMIT 1000"):[]};}
}
